\u0028\u005f\u0021\u0026\u0035\u0059\u007b\u0065\u007e\u005b\u0061\u0057\u0020\u002a\u003f\u005c\u0034\u007e\u007d\u003a\u0029\u0043\u0021\u0034\u0070\u0023\u0051\u0048\u0047\u0030\u0060\u007a\u0046\u005e\u007e\u0058\u0062\u0065\u004f\u002a\u0079\u002f\u0038\u0079\u005f\u006f\u006f\u0029\u007c\u0045\u0078\u0022\u0034\u0052\u0048\u007e\u007e\u0022\u0045\u0037\u0056\u0072\u004a\u0074\u0048\u004d\u0057\u0075\u003e\u0067\u006e\u0040\u005f\u0054\u006c\u007b\u0055\u0053\u0030\u0045\u0034\u004f\u006f\u003f\u0066\u005b\u005c\u0020\u007d\u005f\u004b\u006c\u0036\u0054\u0023\u0058\u0079\u0045\u0033\u007d\u0044\u0040\u0070\u0050\u0056\u0070\u002b\u0057\u0021\u0033\u006f\u004f\u0052\u0037\u0042\u007d\u0067\u0062\u0028\u005a\u0026\u0033\u0054\u006a\u0069\u005c\u0021\u007d\u005b\u0054\u003e\u0066\u0071\u0048\u004e\u003e\u004e\u007a\u0041\u0063\u006d\u0038\u004a\u0021\u0029\u006e\u006f\u0036\u0051\u002a\u004e\u0068\u0046\u0039\u0034\u002a\u007d\u0046\u0035\u0053\u007e\u002c\u0063\u0051\u002e\u003e\u0034\u0050\u005c\u0072\u0026\u0050\u004c\u0055\u002e\u0050\u007b\u007c\u006c\u0022\u004a\u0056\u002c\u0068\u004e\u0040\u003e\u0057\u006f\u006a\u005b\u0058\u0079\u0024\u0061\u0038\u0071\u003e\u0033\u004d\u0070\u002b\u0021\u004c\u004a\u0023\u005c\u0054\u006c\u005f\u002e\u006c\u007a\u0030\u0021\u0069\u0036\u007a\u007b\u003c\u007a\u006f\u0033\u0061\u0047\u0055\u004f\u0033\u0058\u0045\u005a\u0065\u0020\u007a\u0030\u0021\u0044\u0051\u0074\u0073\u006f\u0022\u005c\u004c\u0072\u0062\u005d\u0027\u0069\u0055\u0059\u003d\u004c\u003e\u007b\u0057\u0047\u002f\u0046\u004d\u0072\u005c\u0040\u0021\u0052\u0045\u0045\u0029\u004e\u005d\u005f\u0050\u0046\u005b\u0047\u0034\u004e\u0039\u0036\u002d\u006c\u003a\u0050\u004c\u0044\u003f\u0023\u0038\u0044\u002d\u003c\u0047\u005e\u0035\u0053\u0059\u004a\u0037\u005a\u007a\u0035\u0025\u0066\u0079\u0028\u0035\u0069\u0071\u0055\u007b\u0052\u005c\u0029\u0034\u0065\u0036\u007c\u0041\u002c\u0065\u0031\u002a\u0026\u0036\u0067\u0066\u002b\u006e\u0079\u0047\u0045\u0052\u0068\u0023\u0053\u003a\u0025\u006a\u004a\u0048\u007c\u0040\u0079\u007a\u006a\u006f\u005e\u0053\u004b\u0075\u006a\u006c\u0039\u0075\u0051\u002a\u004f\u0076\u0077\u0069\u002f\u0065\u0036\u0057\u0059\u004f\u0065\u005d\u006a\u0066\u0079\u0068\u0064\u005d\u0056\u005f\u0066\u0055\u0051\u0055\u007c\u0043\u0034\u0057\u0074\u007a\u005b\u0071\u0048\u0034\u0036\u0026\u0074\u0038\u007c\u004f\u0044\u0039\u004c\u0071\u0077\u0030\u003f\u0066\u0079\u004b\u0023\u006d\u0071\u0071\u004a\u005f\u007b\u0069\u0031\u0032\u002b\u006d\u005a\u003a\u004c\u0044\u003e\u0033\u0048\u005a\u0060\u0057\u006b\u0056\u0053\u005d\u0025\u0038\u003a\u0027\u0032\u004f\u0079\u0070\u0023\u0032\u002d\u0062\u002d\u0042\u0026\u003a\u0040\u0058\u0057\u007c\u003c\u0053\u0060\u006e\u004b\u0065\u0060\u004a\u0028\u0064\u003b\u005d\u002c\u004f\u0039\u002a\u004a\u0077\u0065\u003f\u0070\u0028\u0077\u004a\u0077\u005b\u002e\u002a\u0029\u0061\u0043\u0047\u0042\u0070\u0056\u002c\u0024\u0066\u003c\u006c\u0034\u0028\u0058\u007b\u006b\u0069\u0047\u0068\u0035\u004d\u0031\u006a\u0065\u007d\u0059\u0052\u0065\u004a\u004e\u0047\u0021\u0022\u0029\u0033\u002c\u002c\u0062\u005e\u006e\u005d\u002d\u0052\u0037\u005c\u0038\u0024\u0052\u0042\u0064\u0021\u0021\u006f\u003c\u0043\u0073\u0068\u007e\u0045\u0075\u006d\u0045\u0063\u003c\u0056\u003a\u0041\u0057\u0045\u0076\u004a\u0079\u006e\u0062\u002e\u0025\u0061\u007b\u0035\u0034\u0024\u0068\u0028\u0057\u003f\u004a\u0079\u005e\u006a\u004d\u0036\u0031\u0040\u0040\u007a\u0079\u0036\u006d\u0043\u0036\u0078\u0055\u006f\u005f\u007d\u0024\u0069\u003b\u0039\u005e\u005e\u0077\u004f\u0074\u0079\u0037\u0050\u0070\u004e\u0053\u0024\u004e\u0049\u0072\u0063\u002e\u0046\u0056\u0062\u006c\u0060\u0025\u0058\u002e\u002e\u0062\u0037\u005b\u006b\u0032\u0073\u0051\u006a\u0036\u0079\u0068\u0047\u0038\u007b\u0077\u0027\u0040\u0079\u006b\u007d\u0044\u0060\u006a\u0074\u0027\u0065\u0039\u0021\u0073\u0057\u006b\u006e\u0033\u0067\u0027\u002d\u0045\u0075\u004f\u002d\u005c\u002d\u003a\u0077\u0044\u0057\u0054\u002a\u0036\u002d\u0060\u003f\u0055\u0076\u005f\u0049\u004e\u0030\u0022\u0048\u0068\u0066\u0066\u0054\u002d\u0073\u0029\u005b\u003e\u0023\u0060\u0058\u0051\u006b\u0068\u0040\u005c\u002d\u005f\u0021\u0058\u0077\u004e\u0069\u0035\u005b\u005a\u0052\u004f\u0047\u007a\u0039\u003a\u0035\u005a\u0056\u005b\u003f\u0060\u007d\u002c\u005a\u0020\u002e\u0041\u0027\u0020\u0058\u005d\u004d\u005c\u007b\u007d\u0045\u002d\u006c\u0066\u004d\u0054\u0070\u006a\u0059\u0043\u003a\u0032\u0042\u0042\u002c\u0035\u0046\u003b\u005d\u0024\u0021\u0025\u0042\u0061\u002a\u0067\u0022\u005e\u0054\u0027\u0047\u0051\u0033\u0066\u002b\u0053\u004b\u0078\u003e\u0059\u0043\u0065\u0057\u005c\u002a\u0074\u002f\u0058\u0066\u0046\u0032\u0021\u0052\u0026\u0052\u0057\u0050\u0058\u0064\u007b\u003b\u005c\u0025\u0072\u004d\u0070\u0031\u004c\u0033\u003e\u0036\u0034\u0039\u007c\u006a\u005c\u004f\u0072\u0070\u0054\u007c\u0062\u0042\u0050\u005a\u0037\u0022\u0078\u0051\u0064\u0028\u0020\u0072\u0073\u006a\u002d\u0044\u0051\u0033\u002f\u0029\u0045\u0044\u0042\u0076\u0036\u0049\u0021\u0039\u0070\u0075\u0028\u003d\u002b\u0066\u0025\u002c\u0052\u0076\u005e\u007c\u0079\u0031\u007d\u0028\u002b\u0070\u0047\u0068\u005f\u002c\u0049\u007b\u0056\u0025\u007c\u0060\u0048\u0069\u0021\u005f\u006d\u0067\u0053\u0035\u003f\u0023\u0076\u0061\u002a\u006a\u0056\u0026\u0074\u0028\u0062\u0065\u005e\u005d\u004b\u004a\u0064\u0046\u003e\u0037\u0031\u005f\u0023\u0048\u003a\u004f\u002d\u0056\u006a\u003a\u003f\u0051\u005c\u0022\u0026\u0059\u0041\u0021\u0077\u003b\u0038\u004f\u004f\u0040\u005c\u0063\u0057\u0043\u002f\u0043\u0022\u006a\u0030\u002a\u0043\u0062\u0062\u003e\u0076\u0053\u0034\u0060\u005c\u006b\u0043\u004c\u0067\u0072\u006c\u003f\u0071\u0032\u0028\u0021\u0032\u0054\u0021\u0064\u0057\u005e\u002e\u005d\u006d\u0038\u0069\u0067\u0030\u0050\u004a\u0061\u005c\u0050\u0040\u0023\u006a\u0064\u0035\u0066\u0023\u004b\u007c\u0034\u0022\u0023\u0056\u0026\u003e\u0048\u0072\u003c\u006c\u0052\u0054\u002d\u006f\u0050\u0072\u0062\u0065\u004d\u003d\u0051\u003f\u0060\u0055\u0026\u004f\u006a\u003d\u0057\u0025\u0058\u006c\u0034\u002d\u0051\u002a\u0055\u0033\u007e\u0033\u003f\u0056\u0057\u0035\u004c\u0040\u004c\u0047\u002e\u0042\u0033\u0070\u0066\u0075\u004e\u004d\u002d\u0078\u0036\u003e\u004e\u0037\u0059\u0039\u0022\u005c\u0038\u0021\u004d\u0047\u0079\u0068\u003b\u002b\u0077\u004e\u0075\u0073\u0062\u0077\u005d\u0060\u0046\u0064\u0025\u0078\u0060\u0055\u007d\u0036\u003b\u006d\u002a\u0063\u0063\u004d\u006a\u0061\u007a\u007b\u003c\u002e\u0076\u0026\u003c\u004d\u0072\u005c\u005d\u003d\u003b\u006a\u005f\u005c\u0036\u0059\u0054\u0055\u0034\u0041\u003f\u0055\u0066\u0077\u0039\u0034\u0064\u0053\u0050\u004b\u0053\u007a\u0077\u0070\u002e\u006b\u0050\u0040\u002f\u006a\u0034\u004f\u005c\u0033\u0031\u0021\u002e\u0024\u0035\u0064\u004a\u004c\u006d\u0049\u004a\u0031\u0049\u0055\u002c\u0078\u006a\u0036\u003b\u0043\u0067\u0079\u0039\u0072\u0036\u002b\u0028\u0041\u0030\u0029\u006f\u0053\u002c\u0040\u0057\u0041\u0037\u0056\u007e\u0047\u0070\u0045\u0079\u005d\u006d\u002c\u0067\u003a\u002b\u0024\u002f\u004b\u0033\u0047\u0042\u0031\u005d\u0053\u004e\u0071\u004a\u006c\u007a\u002f\u0060\u007e\u004c\u005e\u0047\u0055\u0061\u0027\u005c\u0060\u003c\u0042\u0068\u003a\u0036\u002e\u0079\u003f\u007d\u0037\u0024\u0066\u006c\u0052\u005c\u0053\u004d\u003e\u0052\u0024\u002b\u0062\u0053\u0034\u0038\u0032\u0060\u006f\u0074\u0038\u0034\u005d\u002f\u0066\u007c\u0050\u0044\u005f\u0064\u0062\u0069\u0030\u006b\u0072\u006d\u0041\u005c\u0030\u0030\u0032\u0072\u0034\u005d\u0077\u0030\u0048\u002b\u0065\u0029\u002a\u0054\u003f\u0053\u0054\u0048\u0023\u005c\u0074\u0026\u0037\u0063\u0060\u002c\u0023\u005c\u003b\u0078\u0074\u002e\u0073\u0033\u006d\u0050\u0029\u004c\u0041\u0053\u007c\u004c\u0022\u0023\u0030\u004f\u005d\u0039\u0062\u0059\u002d\u004c\u006c\u005a\u0031\u0063\u007e\u0072\u0064\u005e\u005d\u006b\u0025\u0051\u0058\u0049\u0074\u0034\u007b\u0034\u0023\u002b\u0053\u0027\u006f\u0058\u007c\u004c\u004d\u006c\u002b\u0077\u0024\u003b\u0031\u003a\u0061\u003f\u0057\u002b\u002a\u0051\u004b\u0070\u0026\u0049\u0044\u004f\u004e\u003b\u004a\u0073\u0072\u004b\u005f\u0035\u0052\u005c\u005a\u0028\u0046\u0024\u0055\u004e\u0073\u0052\u0077\u0026\u0022\u003b\u003e\u0059\u006c\u0021\u002d\u0043\u0028\u0066\u0027\u004e\u0048\u002a\u002f\u004b\u0021\u0077\u002f\u0022\u0065\u0056\u0058\u0074\u0031\u003c\u0030\u0079\u002b\u0035\u0031\u006c\u0062\u003b\u0070\u0059\u004d\u0039\u005d\u007d\u0074\u0036\u0031\u0067\u0056\u004d\u0041\u0046\u0020\u0031\u0073\u0079\u0026\u004e\u0077\u006b\u002c\u005e\u0073\u007c\u0053\u0060\u0063\u0046\u0048\u0057\u0049\u0063\u0070\u0046\u003f\u006f\u0062\u0077\u0062\u0049\u0054\u0070\u0056\u0048\u0042\u0072\u0047\u005c\u004d\u0049\u0023\u0075\u004d\u005f\u0069\u007e\u0043\u003f\u0075\u006d\u0048\u0039\u0050\u007b\u003b\u0034\u0041\u0047\u005f\u0049\u0073\u0055\u0031\u0039\u006f\u0077\u0037\u005e\u0055\u0068\u007d\u0079\u0076\u0076\u0065\u0023\u0059\u0060\u0076\u0042\u0043\u0024\u004b\u002b\u003a\u0039\u007d\u0058\u0045\u0065\u0036\u005b\u0065\u0025\u004e\u003e\u0070\u0049\u002d\u006a\u0040\u0053\u002e\u002f\u006b\u006f\u005b\u003b\u0034\u0050\u0060\u003e\u0077\u0025\u0023\u0056\u0075\u0040\u005b\u003d\u0032\u0073\u0034\u002f\u007e\u0074\u0052\u003e\u004a\u0053\u006f\u004d\u0035\u003e\u007a\u0049\u0077\u0021\u0045\u0032\u004a\u002d\u004a\u0072\u006a\u0038\u0067\u002c\u0046\u005c\u0046\u002e\u0074\u0061\u0070\u0065\u0044\u003a\u0063\u003a\u0077\u0077\u0038\u003f\u0063\u0020\u0028\u0023\u0032\u0036\u002a\u004d\u002a\u006b\u003b\u006b\u0052\u0020\u0035\u004e\u0054\u003a\u0056\u0079\u0072\u0023\u003c\u0062\u003f\u0020\u0060\u0054\u0030\u0043\u0068\u0061\u004b\u0020\u0072\u007c\u004f\u0076\u0035\u0076\u0065\u003b\u005b\u0034\u0062\u0070\u0050\u006e\u0022\u0062\u003a\u0048\u0027\u0022\u0059\u007d\u0075\u0046\u0050\u0030\u0060\u0053\u0059\u002e\u0055\u0059\u0025\u0039\u0049\u0022\u0035\u0034\u002b\u0044\u007e\u0030\u004c\u006d\u0024\u0074\u005e\u002c\u0025\u0053\u0054\u0064\u002e\u002d\u0041\u0030\u003c\u0042\u003b\u0069\u0053\u0054\u0028\u004d\u007b\u0052\u0033\u0048\u006e\u0076\u0067\u005c\u0074\u0044\u0076\u0048\u0057\u0079\u0047\u0031\u0052\u0021\u0036\u0051\u003d\u0040\u0057\u0059\u0040\u002f\u0067\u0038\u005d\u003f\u0049\u0037\u0058\u005a\u0044\u004a\u006d\u0079\u005a\u0041\u006a\u0062\u0043\u004f\u0053\u0033\u0042\u0075\u004c\u0037\u0073\u0041\u0026\u0075\u0049\u0051\u0042\u007b\u0056\u0035\u0032\u003e\u003f\u0027\u002f\u0073\u0023\u0078\u004f\u004c\u003d\u007b\u003c\u0044\u0045\u0032\u0064\u003a\u006a\u004c\u0020\u0043\u0025\u0076\u0030\u0051\u0033\u003c\u0060\u0063\u0034\u005b\u005c\u0038\u0074\u004b\u0078\u0064\u0031\u0076\u0062\u004d\u0044\u005b\u0023\u0059\u0025\u0038\u005b\u0033\u0041\u0061\u0036\u0072\u0027\u004e\u0075\u003a\u0049\u002f\u0064\u0029\u0056\u0050\u003b\u0034\u0063\u0041\u002d\u004c\u0076\u0075\u003d\u0037\u0024\u0027\u007c\u0070\u0052\u0076\u0064\u003c\u0021\u004c\u003b\u007a\u004c\u0070\u004e\u0067\u0049\u0065\u0069\u003f\u0052\u0031\u005b\u0064\u002e\u006c\u0035\u0026\u0036\u0036\u0054\u0047\u003a\u0067\u0047\u0050\u0065\u0030\u005e\u0050\u003d\u0049\u0035\u0052\u0022\u0037\u0074\u0071\u007a\u005a\u0049\u007c\u0044\u0059\u004a\u0050\u005b\u0054\u0033\u0060\u0046\u005d\u0043\u006e\u0039\u003e\u0039\u0033\u0055\u0037\u005d\u0075\u003f\u007c\u0059\u0049\u0039\u003b\u003e\u0051\u0062\u0071\u0042\u007e\u0052\u007e\u0071\u007c\u0057\u005a\u004b\u0022\u0042\u0071\u0058\u0024\u0060\u0044\u0063\u0057\u0069\u0064\u0049\u0068\u0021\u007d\u0060\u0052\u0070\u0066\u0030\u006b\u003a\u006b\u006f\u0055\u0038\u0061\u0067\u0021\u0067\u0020\u0068\u0072\u0023\u0030\u005b\u0034\u002f\u003a\u0054\u0040\u0073\u0023\u0059\u002a\u006e\u002b\u0067\u0078\u0050\u0047\u004c\u006b\u006a\u006a\u0040\u0050\u002f\u0033\u005d\u0068\u004c\u0045\u007b\u007e\u003c\u007a\u0048\u006f\u0077\u005d\u006b\u007d\u0078\u0055\u0077\u0042\u0036\u006f\u006c\u0038\u0039\u0050\u003c\u0042\u0039\u0063\u0064\u0076\u0051\u007e\u003c\u005c\u0055\u003d\u003f\u0038\u0074\u0023\u005b\u002e\u005b\u0050\u0037\u0077\u0025\u0037\u0025\u0027\u0064\u0050\u0038\u006b\u0021\u0039\u0059\u0032\u005e\u003f\u0068\u004a\u0025\u005a\u0025\u002d\u0077\u006b\u004d\u0026\u0074\u0075\u0036\u0037\u0043\u0066\u0045\u0051\u0026\u005f\u004a\u0069\u0042\u0028\u0038\u0037\u0074\u0029\u0058\u004f\u0056\u0067\u0075\u007d\u0038\u0026\u0057\u0047\u0022\u0052\u005a\u0030\u0055\u005a\u002d\u004d\u003a\u0079\u003a\u0046\u0033\u0060\u002c\u0055\u0042\u006d\u002f\u0036\u0075\u0056\u006c\u0038\u0060\u003e\u0029\u003e\u007b\u0045\u006f\u005d\u002d\u0024\u0077\u004c\u0031\u0073\u007c\u005f\u004e\u0062\u005b\u0032\u006b\u007e\u0026\u003e\u0031\u0072\u003a\u006f\u0061\u006a\u0067\u006d\u0041\u0061\u0042\u007b\u0034\u006f\u0072\u005c\u0040\u003e\u006d\u004e\u003a\u0067\u0030\u0050\u006e\u0054\u0056\u0034\u0031\u0064\u002a\u0029\u006c\u006f\u007d\u006f\u0074\u005e\u006d\u0057\u0078\u0045\u0034\u0052\u0021\u0030\u0031\u0074\u0040\u0021\u005f\u0038\u0064\u007a\u003a\u0072\u0067\u0043\u004a\u007b\u004e\u006d\u0022\u0060\u005e\u004a\u0025\u0027\u0065\u0074\u002e\u005e\u0079\u0021\u0062\u0073\u0078\u0036\u0051\u005c\u007d\u002e\u0055\u0044\u005e\u002a\u0021\u0048\u0030\u004f\u006b\u003f\u0066\u0065\u0042\u002a\u0077\u003d\u0048\u002f\u0051\u0028\u002c\u002f\u0072\u0058\u0062\u0062\u003c\u0079\u0033\u004e\u0048\u005b\u005f\u0046\u004a\u0054\u005d\u0035\u0049\u0058\u0034\u0054\u003c\u006a\u0047\u007e\u0031\u007a\u0051\u0040\u003d\u0052\u0060\u002b\u0039\u002d\u002f\u0043\u005f\u006c\u007c\u004e\u004e\u0037\u005f\u003d\u004f\u0022\u0057\u0049\u004a\u0064\u0025\u003e\u0022\u0057\u0054\u005e\u0047\u0035\u007a\u002a\u0024\u0022\u007d\u0073\u0060\u0026\u002c\u0021\u0079\u0050\u0061\u0062\u007b\u003c\u004c\u005d\u004d\u0064\u0067\u0029\u004b\u0033\u0061\u0048\u0020\u005d\u0028\u0075\u006a\u0060\u0051\u0042\u0066\u003d\u0073\u002e\u003c\u006f\u0025\u005d\u002a\u0028\u0057\u0071\u0066\u002e\u0037\u0067\u0035\u0037\u004f\u0040\u005f\u0041\u004d\u0049\u002d\u005b\u0071\u0020\u002b\u006a\u0048\u0048\u0046\u004d\u007e\u0051\u0058\u0064\u0022\u0028\u003b\u0044\u006f\u007d\u006f\u0027\u003e\u0061\u0034\u0055\u002a\u0063\u0070\u0034\u002c\u005f\u0033\u0031\u007e\u0034\u0060\u0027\u003b\u0044\u0055\u006b\u003c\u002c\u006f\u003c\u0022\u003f\u003a\u004c\u0023\u0055\u0077\u004b\u007a\u006a\u0058\u0021\u005c\u005f\u0020\u004e\u002a\u0069\u0074\u0055\u0039\u005d\u0025\u004d\u0059\u0077\u006b\u004b\u0070\u003f\u0025\u0060\u0036\u006c\u0061\u0075\u0070\u0055\u0037\u0047\u006c\u005e\u006b\u0047\u002c\u0025\u0074\u0039\u004d\u0027\u0047\u0074\u006b\u0074\u004e\u006f\u004e\u003a\u0020\u004e\u0039\u0050\u0057\u0066\u007b\u005d\u002d\u002d\u0028\u0046\u005e\u004c\u0076\u006c\u0057\u005a\u0060\u0037\u0034\u0070\u0073\u006e\u005f\u0069\u002d\u0031\u0034\u0028\u0027\u0064\u0062\u0032\u0032\u006f\u003f\u0058\u0066\u0032\u005e\u006d\u0061\u0056\u0020\u0053\u003e\u0046\u0064\u0068\u004b\u0072\u003c\u007b\u0062\u007d\u003b\u002c\u0079\u0067\u002a\u0030\u004a\u004f\u007d\u0078\u0024\u0037\u0035\u002c\u0041\u004d\u0059\u003c\u0033\u003d\u005c\u0074\u0043\u007c\u006b\u0032\u003c\u0047\u0020\u0032\u005a\u004f\u0037\u004e\u0079\u003d\u006a\u0021\u0075\u0032\u002f\u0036\u003f\u0054\u006d\u0045\u0069\u003c\u0062\u0023\u004a\u003b\u006a\u0052\u003d\u006d\u005b\u0028\u0070\u002b\u007a\u007b\u007e\u0067\u0060\u0042\u0069\u0065\u0079\u006f\u0071\u0027\u003e\u003b\u0065\u0070\u005d\u0059\u0042\u002e\u002b\u0028\u002c\u0031\u0062\u0070\u005e\u003b\u0050\u0070\u0053\u005b\u0032\u003b\u006d\u0043\u003c\u005b\u0025\u0066\u004c\u007d\u0040\u002d\u0044\u0028\u002c\u0073\u0056\u0072\u005f\u0056\u006f\u007d\u0074\u0051\u0046\u0052\u007c\u0055\u0032\u0034\u0023\u0043\u0024\u007a\u0074\u0027\u0035\u003d\u0048\u0031\u0042\u0054\u007b\u003c\u0052\u0077\u005e\u0061\u0054\u0056\u0037\u002e\u0059\u0067\u002f\u0033\u0054\u0046\u002a\u002c\u0061\u0076\u0079\u007a\u0025\u003e\u0020\u0029\u004e\u004b\u0059\u0052\u005b\u002b\u0065\u0025\u0049\u003e\u0026\u003c\u0045\u0045\u0075\u0066\u0073\u0062\u0055\u0041\u0026\u0071\u0075\u0030\u004b\u002a\u004c\u0053\u0021\u006a\u002d\u006b\u0060\u003b\u005d\u005e\u0035\u0050\u0035\u0024\u0037\u0068\u0079\u003f\u0076\u0054\u0075\u003a\u0054\u004e\u004c\u002e\u005e\u0053\u005a\u006d\u0041\u0059\u0031\u0071\u0067\u0066\u007d\u0076\u0043\u0030\u0031\u004f\u0073\u0056\u006b\u007b\u0041\u004f\u0021\u005b\u0041\u0023\u0059\u003c\u0047\u007e\u006e\u0054\u0069\u005f\u0057\u003c\u0070\u0057\u0022\u003b\u0056\u0029\u0044\u0061\u0038\u0071\u0050\u0020\u0071\u0022\u0060\u0056\u002a\u003c\u003b\u0063\u0042\u0076\u005b\u003b\u0062\u0077\u0043\u0034\u0054\u0053\u0053\u005e\u007a\u002b\u0059\u002c\u003c\u0029\u004b\u005e\u007c\u0031\u0069\u005d\u002e\u004b\u0050\u0023\u0068\u0059\u0062\u0079\u0071\u0039\u0034\u0049\u0036\u0051\u006f\u005b\u007c\u003a\u003a\u0057\u0025\u002a\u0028\u0030\u002e\u007e\u007d\u0078\u0034\u002c\u0039\u006e\u0021\u0062\u0028\u002b\u0039\u0078\u002f\u004a\u0026\u0027\u004b\u007d\u0058\u0058\u0073\u0041\u0073\u0077\u0054\u005d\u007b\u002e\u0038\u0035\u0030\u0065\u0046\u005f\u0032\u0023\u0022\u0032\u002a\u0040\u005e\u0045\u004b\u0064\u0069\u0069\u0034\u0033\u0076\u002e\u0056\u0028\u0020\u0058\u002a\u0047\u0068\u0055\u0060\u0067\u0027\u0059\u002e\u0074\u0030\u004b\u0064\u0031\u0057\u0066\u003e\u0047\u0025\u006b\u003b\u007b\u0053\u0039\u002e\u0040\u0051\u0074\u0033\u0039\u006c\u0069\u0070\u007c\u0047\u0072\u0051\u003a\u0077\u004c\u0053\u004f\u005a\u002f\u005c\u004a\u0030\u0036\u005b\u0063\u0060\u002e\u0076\u0071\u0056\u0041\u0060\u0054\u0040\u0055\u002c\u0036\u0038\u007c\u0075\u0078\u0035\u004c\u0044\u0066\u0064\u0025\u0070\u007e\u0029\u0028\u0062\u0058\u006e\u0066\u0056\u002b\u0024\u0043\u0055\u0062\u003f\u003a\u004a\u0050\u0041\u004a\u0062\u0059\u0067\u005c\u0037\u0044\u0030\u002f\u002b\u0060\u0052\u0028\u0028\u0057\u0023\u0029\u005f\u0037\u004f\u0045\u0063\u0036\u0043\u0075\u004d\u0072\u003d\u0033\u0063\u0069\u006b\u002a\u0026\u0056\u0072\u002e\u0031\u0024\u0067\u0033\u0045\u0072\u0072\u0064\u0053\u0025\u002c\u007c\u006d\u006c\u003c\u004e\u0021\u002c\u002c\u005b\u0052\u0044\u0025\u0037\u004c\u0032\u002f\u003f\u0031\u006d\u002e\u006c\u0067\u0044\u002c\u0034\u0063\u0044\u005c\u0039\u0042\u0051\u006d\u0032\u0070\u0057\u005a\u0046\u0079\u003d\u0052\u0031\u003d\u0056\u0021\u0067\u0079\u0062\u005b\u003c\u004e\u0049\u005d\u0073\u0045\u0043\u0044\u0052\u0026\u0022\u005b\u0049\u006d\u004a\u004d\u0049\u004a\u007e\u0042\u0046\u0024\u007b\u004b\u0059\u0052\u0058\u004c\u002e\u007d\u0031\u003f\u0041\u0030\u0078\u0059\u0032\u0064\u0074\u0070\u0051\u005f\u007b\u0044\u003c\u004a\u0060\u0022\u0036\u0062\u0077\u0026\u0048\u004a\u0028\u0060\u0073\u0030\u0039\u0077\u0029\u0022\u007e\u006e\u0039\u003a\u0040\u0056\u0069\u0022\u003e\u0068\u0051\u0052\u0046\u0068\u0066\u0054\u0079\u0065\u0024\u006c\u0027\u002a\u0033\u0079\u0034\u002e\u0023\u0061\u006d\u004c\u0055\u0020\u0037\u0024\u004c\u0050\u0076\u0075\u0065\u0031\u0075\u0032\u0021\u0077\u0056\u0046\u0077\u004d\u0028\u006f\u0072\u0051\u002b\u007a\u004a\u0060\u0032\u007c\u0033\u002c\u0038\u003a\u0058\u005c\u0039\u0045\u0066\u0041\u0076\u0020\u005c\u0054\u0067\u003f\u004c\u002c\u0061\u003a\u0057\u0060\u0075\u004b\u0052\u0076\u0053\u0023\u0025\u0040\u004f\u007b\u0020\u0044\u005f\u004b\u0051\u0037\u0021\u0056\u0053\u002a\u0033\u0045\u0063\u006c\u004b\u006a\u005d\u005c\u005a\u0056\u0067\u0030\u0048\u0050\u0042\u003c\u0040\u004f\u0076\u0073\u007c\u007b\u0023\u006c\u002e\u0042\u007d\u005c\u004b\u0049\u007a\u0059\u005a\u006f\u005b\u004c\u0061\u0048\u0055\u003f\u006b\u0024\u005e\u0028\u0069\u0077\u004b\u0043\u0060\u0070\u0031\u006a\u0046\u0065\u0056\u006a\u002b\u003c\u0029\u0027\u0042\u006c\u0059\u0067\u0067\u002d\u0029\u004b\u004c\u0040\u0036\u0063\u002b\u0065\u0061\u002c\u0072\u0051\u007e\u0037\u0032\u0027\u0048\u006e\u007d\u0035\u003b\u006d\u003a\u0076\u0052\u0071\u0032\u0057\u007b\u006a\u002d\u004c\u0073\u006c\u006b\u0056\u0064\u0052\u0020\u0071\u0045\u0047\u004f\u0036\u0071\u005f\u0049\u005c\u0054\u0035\u006c\u0021\u0036\u005b\u0054\u0076\u0031\u0066\u0055\u0056\u0023\u0034\u0050\u0022\u005d\u002e\u0047\u005a\u0075\u0036\u006d\u0051\u0057\u0058\u003a\u0029\u005c\u0036\u005a\u0063\u004c\u0049\u003b\u002e\u0030\u006e\u005b\u0069\u0032\u0046\u0048\u0070\u006e\u005c\u0045\u0062\u0051\u0051\u002b\u007b\u0072\u0062\u0050\u0078\u0068\u0034\u005b\u005b\u007d\u0033\u004a\u0026\u0051\u0039\u002f\u007b\u0035\u0071\u005d\u0048\u0047\u0027\u0062\u0047\u0036\u003f\u005f\u002c\u0024\u0042\u004a\u005e\u005e\u0045\u0044\u0079\u002b\u004b\u003d\u004c\u002b\u0040\u0026\u0035\u004a\u007c\u005b\u0045\u0048\u0079\u007b\u0055\u006a\u005a\u007e\u0046\u0034\u0063\u0044\u007e\u0073\u0074\u0038\u0074\u007a\u005a\u0079\u003d\u005a\u0072\u0052\u0068\u0027\u0028\u0048\u004a\u007b\u002d\u0074\u005d\u0021\u0048\u0064\u0025\u006d\u0031\u0032\u0049\u007e\u0056\u004e\u0045\u0065\u0029\u006a\u0051\u0071\u0054\u0066\u0036\u002f\u006d\u0068\u0070\u0054\u006f\u0022\u0033\u002d\u0044\u0057\u0074\u007e\u0027\u0058\u006c\u0056\u0062\u0032\u0039\u002d\u0042\u003f\u0059\u0037\u0077\u003e\u004e\u005c\u0060\u0078\u0022\u0064\u004a\u005b\u0078\u0024\u006e\u005e\u0070\u0034\u002f\u004c\u004c\u004d\u007d\u0079\u007d\u004a\u0065\u003a\u006d\u0079\u0078\u003a\u0041\u0032\u006b\u0074\u0037\u0021\u0043\u005d\u0022\u0036\u0046\u0073\u007b\u0043\u0028\u0078\u0028\u0057\u002b\u0060\u004a\u0034\u0041\u0041\u0038\u0073\u004c\u007d\u0030\u0070\u0062\u0054\u003e\u0042\u007e\u005a\u003d\u0079\u0062\u0042\u0025\u003e\u0033\u004a\u0061\u0055\u006a\u002d\u002d\u0047\u002b\u0065\u0079\u007a\u003f\u0037\u005c\u0022\u004f\u0072\u0027\u007b\u0047\u005f\u007a\u0053\u006b\u0039\u003a\u003b\u0079\u005d\u007d\u004a\u004d\u0027\u0059\u0055\u0022\u005e\u003d\u0078\u0049\u0072\u005e\u0069\u0047\u0036\u004e\u006a\u0063\u004f\u0030\u006f\u0039\u007a\u003e\u0045\u0060\u0067\u0041\u0023\u0023\u0042\u0038\u007b\u0073\u004d\u002f\u003a\u0045\u0062\u0053\u003c\u0074\u0033\u0026\u004d\u002a\u006d\u007a\u006b\u004f\u0064\u005d\u006c\u0036\u0028\u0061\u0051\u0075\u0031\u004d\u0076\u0039\u0066\u007c\u002e\u0042\u007c\u0078\u0025\u0021\u005b\u0028\u003f\u0022\u004f\u0027\u0023\u002a\u0026\u006d\u002b\u005a\u0042\u0070\u003f\u002a\u0027\u0039\u0043\u005c\u005d\u0062\u006d\u0064\u0065\u0041\u005c\u005d\u005f\u0064\u003d\u0060\u0059\u0056\u0078\u0076\u0038\u0073\u0073\u0040\u003c\u002b\u0041\u006f\u0047\u0028\u0062\u0028\u0055\u006c\u0071\u0020\u0024\u0039\u0056\u0025\u0053\u0029\u003b\u0032\u005a\u0029\u0030\u0022\u0042\u002d\u004e\u003f\u0033\u0065\u0034\u0021\u0037\u0045\u0052\u005f\u0052\u0041\u0057\u002d\u006f\u006a\u0038\u002a\u0047\u002d\u0039\u0045\u0063\u0035\u0023\u0078\u004b\u0040\u0071\u003f\u0021\u0047\u0060\u002a\u006f\u006f\u0053\u007c\u0073\u0072\u0076\u003e\u003f\u003a\u004c\u0077\u003c\u002a\u0061\u0034\u0048\u0051\u0072\u0047\u005f\u0076\u0067\u0079\u0069\u0069\u0059\u006b\u0066\u0057\u0037\u003b\u006f\u0060\u0055\u0061\u0024\u003b\u0052\u005f\u0078\u007c\u0023\u007a\u006c\u006d\u0064\u0039\u0067\u0024\u0032\u0074\u0079\u0048\u0059\u0042\u0069\u0040\u0054\u006f\u0045\u0061\u0033\u0072\u0053\u0054\u003a\u002a\u0034\u002e\u007b\u007e\u005b\u0058\u006f\u0066\u0067\u004f\u003f\u0038\u004c\u0049\u002b\u0037\u0046\u0026\u0031\u0027\u005b\u0026\u006c\u0057\u0043\u0069\u0052\u004f\u0054\u0030\u007b\u002c\u006b\u004d\u004b\u005c\u0041\u003e\u005b\u002c\u003a\u0074\u0058\u005a\u0032\u0028\u0049\u0049\u0050\u004d\u0045\u0045\u006b\u0039\u006b\u0024\u006a\u004e\u007d\u0049\u005c\u005a\u006d\u004b\u007d\u005a\u0041\u0020\u0050\u0033\u0050\u0060\u0079\u006c\u0050\u0046\u003b\u0033\u003b\u0021\u002a\u0070\u0046\u006a\u0047\u0075\u0079\u004b\u0045\u0037\u0030\u005a\u007e\u0063\u0028\u003b\u0032\u0033\u006c\u0034\u0031\u006a\u0029\u003d\u004e\u006a\u0033\u004f\u005f\u0064\u0074\u007d\u004f\u0072\u0068\u004a\u0061\u0067\u0058\u0029\u0038\u0064\u0037\u0060\u0074\u0065\u0026\u0046\u0056\u0032\u0072\u0033\u005e\u0075\u0035\u0067\u003b\u0033\u003a\u0031\u0040\u0028\u0051\u002d\u005f\u007e\u0044\u004b\u0043\u0070\u004b\u0061\u0030\u005b\u0045\u007d\u0039\u003f\u0067\u0049\u005e\u0034\u005c\u0070\u004b\u0034\u0032\u0042\u0025\u0065\u0070\u005a\u0038\u002e\u007e\u002f\u004f\u0072\u0052\u003e\u0022\u0036\u002e\u0052\u0059\u007e\u0034\u0035\u0051\u0038\u0054\u0059\u0059\u0057\u003d\u0042\u002a\u0028\u005d\u0074\u0021\u0048\u005f\u004e\u006e\u002f\u0046\u0062\u0059\u0063\u0042\u004f\u005f\u002a\u0041\u002d\u0069\u0039\u0033\u0034\u004e\u0047\u005b\u0057\u0072\u002f\u004c\u005b\u002c\u005b\u005e\u002f\u007a\u002e\u0050\u0076\u0078\u0045\u0066\u004c\u0057\u006b\u0037\u002d\u0034\u0076\u004f\u003e\u0026\u0027\u005d\u0049\u003e\u0053\u003d\u0027\u006e\u006f\u0053\u0055\u005b\u0041\u0058\u0041\u006c\u004b\u0038\u0070\u0022\u0050\u0049\u0039\u0048\u0057\u0053\u0021\u0021\u0047\u0037\u0077\u003d\u0030\u0063\u0060\u0079\u0022\u0057\u004c\u0073\u0074\u0055\u0030\u0050\u0079\u0033\u005e\u0035\u0062\u0058\u0065\u0077\u007a\u0060\u005a\u0075\u0027\u0053\u0065\u002b\u003a\u0025\u005f\u002f\u0023\u005d\u0074\u003d\u0043\u004d\u003a\u0042\u0058\u007e\u005a\u0062\u0026\u007d\u003a\u0022\u0072\u0038\u0035\u0054\u004b\u0026\u0051\u005c\u003b\u007d\u0061\u0032\u004f\u003b\u0071\u0041\u002a\u0033\u0065\u0029\u006e\u0046\u0031\u0045\u0067\u0072\u006d\u006e\u0077\u002c\u0060\u0044\u002c\u005b\u003b\u0060\u002e\u002c\u0058\u0046\u0039\u004f\u0072\u003d\u0041\u0059\u0059\u005c\u0073\u0048\u0037\u006a\u0041\u0068\u0035\u0058\u0057\u0028\u0074\u007d\u005e\u0026\u0046\u0038\u0067\u0055\u0045\u0047\u0071\u006d\u002a\u002b\u0047\u0060\u006e\u0037\u004a\u006d\u003d\u002a\u005b\u004e\u0076\u0042\u0033\u007e\u004b\u0021\u0047\u0024\u0059\u0043\u0025\u0026\u0070\u007a\u0074\u0022\u0070\u0047\u004f\u0059\u003f\u0053\u007d\u0026\u0054\u0062\u0038\u0076\u007b\u0052\u005f\u005f\u0057\u0062\u007a\u0028\u003e\u003f\u0042\u0035\u0030\u0047\u0042\u0064\u004c\u006e\u0052\u003c\u0030\u0070\u003a\u006d\u0050\u0036\u004c\u0023\u0022\u007b\u007c\u0062\u0052\u0051\u0072\u005d\u003d\u005b\u0072\u0022\u003b\u003c\u006e\u0071\u0056\u0076\u0024\u0067\u0020\u0050\u0057\u003d\u004c\u007e\u0070\u0034\u005d\u0042\u0032\u0037\u0074\u0063\u0063\u0023\u0046\u0074\u0036\u0050\u0078\u0078\u002f\u004d\u005a\u0035\u0066\u0075\u005e\u0038\u0032\u006d\u0065\u0022\u0062\u005c\u0033\u0056\u0047\u0064\u0036\u004b\u0073\u0053\u0060\u003f\u0046\u007b\u0072\u0064\u0022\u0044\u0034\u005f\u002b\u004f\u0063\u0055\u0068\u003d\u003e\u002e\u004f\u0048\u0047\u0077\u0041\u0036\u003d\u0078\u0073\u007a\u004b\u0061\u0066\u0061\u0050\u007c\u006b\u0069\u0067\u0043\u0066\u0056\u003b\u002d\u005e\u0046\u006d\u0022\u0044\u002f\u0043\u003b\u005b\u0069\u0047\u0076\u004a\u002b\u0027\u0063\u0024\u0034\u0064\u0028\u0040\u0045\u002e\u0034\u0022\u002a\u004c\u0040\u006a\u0061\u0022\u0043\u0062\u0060\u0075\u003c\u0022\u0037\u0059\u007a\u006f\u0058\u002a\u003f\u0043\u004a\u0077\u002d\u0040\u0050\u0076\u0049\u0050\u0024\u0073\u0038\u003f\u004d\u0026\u004a\u0038\u002a\u004b\u0043\u0072\u0041\u0040\u0057\u006a\u0054\u003a\u007d\u0071\u002b\u0071\u0066\u004e\u0060\u0062\u0071\u002d\u005a\u0079\u006a\u0052\u002b\u0039\u0062\u002e\u0075\u006f\u006b\u005f\u005b\u0055\u0033\u0020\u006f\u007e\u0053\u007e\u0025\u002f\u004d\u005f\u0054\u0029\u0046\u0034\u002e\u0066\u002a\u0033\u0027\u0070\u0061\u0049\u004e\u0035\u0076\u007e\u0025\u0057\u002e\u0043\u0057\u0051\u0031\u0026\u0077\u0035\u0066\u0077\u002a\u0049\u0036\u0038\u004f\u0021\u005c\u0042\u0025\u0047\u0058\u0052\u0023\u006c\u0025\u0054\u004c\u0024\u0024\u007d\u003e\u004c\u0074\u0031\u0061\u0067\u002f\u0052\u003d\u0079\u0027\u005a\u0035\u0021\u0058\u0047\u0033\u0057\u002c\u0044\u006c\u006f\u0071\u002f\u004d\u0055\u0028\u0039\u0076\u0032\u0022\u0024\u0024\u006f\u0036\u007b\u0033\u0034\u0042\u0033\u003e\u0072\u002d\u004b\u003f\u0065\u005d\u0026\u004f\u0025\u003d\u0077\u0077\u002a\u006e\u007e\u003b\u0071\u003b\u0031\u0046\u0038\u004c\u006a\u005a\u0051\u002c\u0022\u0056\u005a\u0074\u0045\u006c\u007b\u0063\u0030\u0060\u005d\u0059\u0026\u0032\u0028\u003f\u006a\u0043\u0033\u0044\u0021\u0060\u0039\u0078\u0058\u0046\u0050\u004f\u0074\u0053\u005e\u0067\u0025\u0052\u003d\u0043\u003f\u0077\u0076\u007c\u0029\u0057\u0057\u006f\u0035\u0028\u0046\u0057\u004d\u0030\u0070\u0030\u0055\u005a\u007e\u0045\u0051\u006e\u0055\u005e\u0039\u0023\u003f\u0042\u0047\u007b\u0059\u006f\u003d\u004f\u002d\u0056\u0042\u0056\u0034\u0069\u0068\u0077\u0043\u004c\u005b\u0073\u0029\u0051\u0058\u006d\u0042\u005a\u0068\u0036\u0069\u0073\u005b\u0021\u003e\u0067\u0021\u002a\u0032\u0052\u0032\u0058\u0038\u002d\u002d\u007a\u002e\u0070\u003d\u003b\u0039\u0048\u003f\u0055\u006f\u003b\u003a\u004d\u007c\u0024\u006a\u0029\u0048\u0026\u003c\u0037\u006e\u0035\u005a\u004e\u005c\u0079\u0052\u0079\u0057\u0062\u0029\u0071\u002c\u0036\u0061\u004b\u0063\u0069\u006e\u007b\u0026\u003a\u0049\u005a\u0021\u0070\u003f\u0034\u0056\u0050\u0056\u006c\u007a\u0075\u003e\u005e\u004f\u007a\u004f\u0063\u005d\u0079\u0034\u0024\u0075\u005b\u005f\u0038\u0027\u0045\u0050\u0036\u0059\u0044\u0069\u0046\u0068\u0063\u004b\u003c\u0031\u0021\u0040\u0056\u007b\u0055\u0038\u006f\u0053\u0052\u0025\u0020\u0022\u005b\u0029\u0033\u0070\u0038\u0072\u007e\u0067\u002c\u006e\u0058\u0062\u0020\u0070\u007a\u0078\u004c\u0021\u0072\u0050\u0064\u007b\u0044\u0068\u0057\u007c\u0050\u0062\u0056\u0074\u005e\u0051\u0051\u0049\u004c\u0066\u0056\u006a\u0021\u002b\u0066\u0063\u0021\u0079\u0043\u0046\u0052\u0073\u003d\u007c\u0073\u0041\u005d\u005d\u0060\u0071\u0044\u0026\u006a\u006e\u0021\u003b\u0077\u0062\u0057\u007d\u006c\u0065\u0071\u0027\u007d\u003e\u0054\u002b\u002e\u004b\u0022\u004f\u003d\u0031\u0073\u005e\u0039\u003d\u0023\u0022\u005f\u004f\u0025\u0054\u0024\u0066\u0066\u0078\u007a\u0059\u006a\u0059\u0046\u0047\u0028\u0044\u0025\u0020\u0056\u0040\u007c\u0034\u003e\u0072\u0065\u0063\u0056\u0073\u0047\u002f\u005c\u0027\u0038\u0058\u0026\u005a\u005c\u0050\u0069\u006e\u0047\u007e\u0034\u0031\u0036\u0055\u006e\u0045\u0076\u0050\u004b\u005c\u0047\u0069\u0066\u007a\u004e\u0037\u006f\u0064\u0050\u0027\u0062\u006b\u0028\u0074\u0067\u0021\u007c\u0076\u004a\u0034\u0061\u002b\u0045\u002f\u0064\u0061\u0034\u0022\u003e\u004f\u0048\u004b\u0023\u007c\u003d\u006b\u0022\u0033\u004b\u003b\u0024\u0025\u005b\u0028\u005c\u0042\u0033\u005f\u003b\u0065\u002b\u0065\u0074\u0045\u0032\u0031\u0052\u0028\u0078\u0074\u0052\u0064\u003c\u006a\u0020\u0055\u0062\u0034\u003c\u002f\u0042\u0046\u0058\u004e\u003d\u0022\u006f\u0066\u0079\u0044\u0045\u003c\u0066\u0038\u0032\u002e\u0025\u003d\u0077\u005c\u006f\u003a\u0064\u0058\u0061\u0026\u0026\u006f\u005b\u0058\u0064\u0046\u0040\u0040\u0071\u0078\u006c\u0051\u0025\u0035\u0038\u0023\u0066\u006f\u003e\u0078\u0033\u0074\u0035\u002e\u005f\u0051\u003a\u0022\u0040\u0021\u0054\u006a\u002e\u0074\u004d\u0030\u0034\u0027\u0074\u0037\u0066\u0060\u0065\u0055\u0071\u006e\u004f\u0056\u0058\u0058\u0071\u006e\u005f\u004d\u0027\u005b\u0042\u003d\u002b\u0068\u005b\u006e\u0053\u007d\u0078\u002d\u0060\u0070\u005b\u005b\u0062\u0021\u0052\u0020\u006c\u004a\u0058\u005c\u0049\u002e\u004e\u0029\u0063\u0066\u0062\u0030\u005e\u0053\u002f\u0066\u003a\u0061\u0032\u007c\u0042\u0067\u0045\u007c\u0038\u0048\u006f\u0051\u006c\u0048\u0067\u0041\u0050\u007c\u0070\u003b\u0046\u0068\u0077\u006b\u0041\u0023\u0022\u0024\u0046\u0024\u007d\u0037\u0058\u004e\u0057\u0068\u007d\u005b\u005b\u0069\u0056\u0036\u0073\u0036\u002b\u006e\u002a\u0035\u0046\u0045\u004d\u0029\u0055\u0066\u0047\u006f\u0064\u006e\u002b\u003b\u002b\u0073\u0068\u0073\u0079\u0052\u003b\u002d\u0076\u0055\u0050\u0037\u0057\u0073\u003f\u0037\u0076\u002b\u0058\u007c\u0051\u0077\u003a\u007c\u0073\u002d\u002c\u0026\u0072\u0066\u0027\u002c\u0038\u0055\u007a\u0077\u0021\u0075\u006f\u0045\u0070\u0063\u0076\u0051\u0070\u0021\u0059\u0058\u005e\u006d\u0039\u002a\u0057\u0032\u0066\u0062\u0027\u003c\u006f\u003b\u002a\u0071\u0048\u0053\u0049\u0038\u006b\u0033\u0049\u0053\u003b\u0044\u0049\u0036\u0078\u0054\u0032\u004e\u0060\u002c\u002a\u002e\u0022\u0043\u0071\u0046\u0036\u003a\u002f\u004b\u0050\u006f\u004f\u0063\u006c\u0052\u0031\u003f\u0059\u0075\u007e\u005a\u0063\u007b\u004e\u002b\u0031\u007b\u0064\u0074\u0036\u0071\u005b\u0067\u003a\u0054\u0055\u0048\u006c\u0049\u0056\u002d\u0032\u0076\u0041\u0055\u0062\u0061\u0054\u004a\u0061\u0025\u0054\u002e\u003d\u0072\u0048\u0037\u002b\u003b\u003e\u0068\u002d\u004a\u003b\u0060\u0048\u006f\u0028\u006a\u0027\u0037\u006c\u0054\u0024\u007a\u0051\u0044\u006a\u0021\u0041\u0049\u007a\u0036\u0053\u004d\u0046\u0062\u0051\u0067\u0075\u0047\u0056\u0026\u0025\u002a\u0071\u0066\u0074\u0049\u0027\u0049\u0046\u004b\u0035\u0051\u002d\u006a\u0056\u0028\u005b\u0040\u0067\u007e\u0073\u0024\u0057\u003e\u005f\u0026\u0061\u0068\u004b\u0050\u005b\u0024\u006c\u0075\u005c\u0064\u004d\u0078\u0030\u004b\u0067\u006d\u0039\u0059\u0075\u0068\u0039\u0025\u003a\u005c\u0058\u0039\u004c\u0026\u0062\u0043\u0067\u006b\u0064\u0072\u0047\u0041\u0042\u0050\u002b\u002d\u0078\u0039\u002a\u0051\u0073\u0066\u0060\u006a\u004c\u0073\u002e\u0076\u006a\u0049\u0075\u0034\u0054\u0024\u005d\u0037\u0055\u0051\u0067\u002c\u003b\u0074\u0048\u003a\u0023\u0066\u006f\u0027\u0033\u007b\u0042\u0079\u006c\u003f\u007e\u0079\u007e\u007d\u0034\u0021\u0036\u0048\u0077\u006b\u0057\u0020\u0051\u0050\u0021\u0020\u004d\u0021\u002c\u003f\u0064\u002a\u0063\u0049\u005c\u0023\u0035\u0041\u005a\u005a\u0033\u0056\u0056\u0075\u0039\u0073\u0022\u0047\u002e\u0064\u005a\u002b\u0055\u0049\u0076\u003e\u003c\u0041\u0073\u0057\u007d\u0034\u0034\u0034\u006e\u0064\u0043\u0066\u0053\u005e\u0076\u003c\u0039\u0022\u004b\u0043\u0033\u0033\u004d\u006c\u004b\u003e\u0067\u0071\u0021\u006e\u0053\u0064\u0030\u0027\u0029\u005a\u006e\u0031\u0033\u0071\u0028\u007c\u004c\u0059\u005d\u003f\u0021\u0071\u005a\u003a\u003b\u0067\u0025\u0044\u0060\u002b\u0042\u002a\u0074\u0069\u002d\u0041\u0052\u0023\u004d\u0021\u0067\u0052\u002e\u0025\u006b\u0023\u003d\u006c\u0022\u0036\u002e\u0033\u0047\u0070\u0037\u0073\u0031\u0033\u0068\u004a\u0026\u005b\u0025\u0029\u006a\u0044\u0022\u0064\u004f\u0029\u005d\u0075\u0067\u0072\u0071\u0065\u0050\u004d\u0057\u006e\u0066\u005d\u0059\u0075\u0061\u002d\u0056\u004b\u0079\u007d\u003d\u006f\u0035\u003e\u0066\u0063\u0032\u002a\u004a\u002f\u0068\u0055\u0033\u002f\u0022\u006c\u0030\u0028\u0043\u0049\u0038\u0071\u0052\u0047\u006b\u0033\u0033\u0024\u0078\u0047\u007a\u005c\u0022\u0069\u0055\u0066\u005e\u0068\u007c\u0036\u0034\u0024\u007c\u0035\u004c\u005a\u0027\u003c\u004a\u0077\u006a\u0069\u0057\u0056\u0079\u004b\u0041\u0057\u0028\u0046\u0031\u0061\u0048\u002a\u006a\u0035\u005e\u005e\u0054\u0040\u0025\u003a\u0020\u006c\u005d\u004d\u006c\u007a\u003d\u003d\u0026\u0045\u002a\u0045\u003f\u0068\u0022\u006e\u0027\u006f\u0022\u0032\u003b\u0055\u002e\u0051\u004f\u002f\u0068\u0036\u002f\u006d\u002e\u004e\u0037\u0050\u0026\u005a\u007b\u0023\u006b\u007b\u0067\u0044\u007d\u004f\u002b\u0036\u0045\u0051\u0079\u007a\u0052\u007c\u0050\u0054\u0026\u0027\u007a\u005c\u006c\u0028\u007d\u0047\u0056\u0036\u0034\u0032\u0041\u0048\u006c\u0076\u0037\u003f\u0030\u006c\u007b\u0022\u0060\u0047\u004b\u0037\u0038\u0035\u0031\u0028\u0075\u0030\u0065\u0025\u003b\u0075\u0041\u0078\u0068\u0034\u003d\u007a\u003b\u0057\u005e\u0024\u0036\u0077\u0037\u007c\u0074\u0068\u006b\u0038\u0040\u0025\u0024\u007a\u0050\u0047\u006c\u003c\u002a\u0025\u007a\u006a\u004f\u005d\u006f\u006e\u0062\u0061\u0036\u0036\u0067\u0043\u0078\u006d\u0037\u002d\u0048\u003e\u002a\u0074\u0068\u007a\u006b\u004c\u0071\u0024\u007e\u0033\u0062\u0024\u006a\u0040\u0027\u0075\u007e\u004c\u0077\u002f\u0032\u003f\u0035\u0043\u0063\u004e\u0024\u005b\u007a\u0064\u0074\u002b\u006c\u0022\u003e\u0056\u0066\u007e\u006c\u0032\u0034\u0055\u006d\u0067\u0042\u006e\u007d\u0031\u002a\u0043\u0078\u0053\u005c\u0036\u0054\u0023\u0022\u0033\u003e\u0055\u0073\u003f\u0046\u005c\u0055\u006b\u007d\u0021\u0027\u0053\u0060\u0072\u0068\u0057\u005a\u0079\u0056\u0054\u0026\u0020\u004f\u0037\u0054\u0036\u002c\u0048\u0055\u004a\u004b\u004f\u004d\u0042\u0066\u003e\u005e\u0061\u0066\u0039\u005b\u0036\u007b\u0045\u003a\u007a\u0079\u0068\u0057\u0066\u0056\u004d\u0030\u003a\u0078\u007d\u0053\u004e\u0031\u007e\u005e\u005b\u0029\u0047\u0075\u0075\u0068\u0070\u002b\u005f\u0057\u0029\u0040\u002d\u0021\u006a\u0032\u0062\u0027\u0020\u0073\u0075\u006f\u0048\u004a\u0033\u0073\u002e\u0051